"java/MainActivity.java": "package com.pandaria.fit;\n\nimport android.os.Bundle;\nimport com.getcapacitor.BridgeActivity;\n\npublic class MainActivity extends BridgeActivity {\n    @Override\n    public void onCreate(Bundle savedInstanceState) {\n        registerPlugin(PandaNativePlugin.class);\n        super.onCreate(savedInstanceState);\n    }\n}\n",
"java/PandaNativePlugin.java": "package com.pandaria.fit;\n\nimport android.content.Context;\nimport android.content.Intent;\nimport android.content.SharedPreferences;\nimport android.os.Build;\nimport com.getcapacitor.JSArray;\nimport com.getcapacitor.JSObject;\nimport com.getcapacitor.Plugin;\nimport com.getcapacitor.PluginCall;\nimport com.getcapacitor.PluginMethod;\nimport com.getcapacitor.annotation.CapacitorPlugin;\nimport java.lang.ref.WeakReference;\n\n/** Puente entre la app (JavaScript) y el código nativo: servicio del entreno y widgets. */\n@CapacitorPlugin(name = \"PandaNative\")\npublic class PandaNativePlugin extends Plugin {\n    private static WeakReference<PandaNativePlugin> instance = new WeakReference<>(null);\n\n    @Override\n    public void load() {\n        instance = new WeakReference<>(this);\n    }\n\n    /** El servicio y los widgets avisan a la app con este evento. */\n    static void emit(String action) {\n        PandaNativePlugin p = instance.get();\n        if (p == null) return;\n        JSObject d = new JSObject();\n        d.put(\"action\", action);\n        p.notifyListeners(\"nativeAction\", d, true);\n    }\n\n    @PluginMethod\n    public void workout(PluginCall call) {\n        Context c = getContext();\n        JSObject data = call.getData();\n        boolean stop = \"none\".equals(data.getString(\"mode\", \"none\"));\n        try {\n            if (stop) {\n                if (WorkoutService.running) {\n                    c.startService(new Intent(c, WorkoutService.class).setAction(WorkoutService.ACT_UPDATE).putExtra(\"data\", data.toString()));\n                }\n            } else {\n                Intent i = new Intent(c, WorkoutService.class).setAction(WorkoutService.ACT_UPDATE).putExtra(\"data\", data.toString());\n                if (Build.VERSION.SDK_INT >= 26) c.startForegroundService(i);\n                else c.startService(i);\n            }\n            call.resolve();\n        } catch (Exception e) {\n            call.reject(\"No se pudo iniciar el servicio: \" + e.getMessage());\n        }\n    }\n\n    @PluginMethod\n    public void getState(PluginCall call) {\n        JSObject r = new JSObject();\n        r.put(\"running\", WorkoutService.running);\n        r.put(\"state\", WorkoutService.snapshot());\n        call.resolve(r);\n    }\n\n    @PluginMethod\n    public void setWidgetData(PluginCall call) {\n        String json = call.getString(\"json\", \"{}\");\n        prefs().edit().putString(\"data\", json).apply();\n        Widgets.updateAll(getContext());\n        call.resolve();\n    }\n\n    @PluginMethod\n    public void consumeWidgetActions(PluginCall call) {\n        SharedPreferences p = prefs();\n        String s = p.getString(\"pending\", \"[]\");\n        p.edit().putString(\"pending\", \"[]\").apply();\n        JSObject r = new JSObject();\n        try {\n            r.put(\"actions\", new JSArray(s));\n        } catch (Exception e) {\n            r.put(\"actions\", new JSArray());\n        }\n        call.resolve(r);\n    }\n\n    private SharedPreferences prefs() {\n        return getContext().getSharedPreferences(Widgets.PREFS, Context.MODE_PRIVATE);\n    }\n}\n",
"java/WidgetActionReceiver.java": "package com.pandaria.fit;\n\nimport android.content.BroadcastReceiver;\nimport android.content.Context;\nimport android.content.Intent;\n\n/** Botón +250 ml del widget de agua. */\npublic class WidgetActionReceiver extends BroadcastReceiver {\n    @Override\n    public void onReceive(Context context, Intent intent) {\n        if (intent != null && Widgets.ACT_WATER.equals(intent.getAction())) Widgets.addWater(context);\n    }\n}\n",
