"res/drawable/pf_sc_fast.xml": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<vector xmlns:android=\"http://schemas.android.com/apk/res/android\" android:width=\"48dp\" android:height=\"48dp\" android:viewportWidth=\"48\" android:viewportHeight=\"48\">\n    <path android:fillColor=\"#FFFF7A1A\" android:pathData=\"M24,0a24,24 0 1,0 0.01,0z\" />\n    <path android:strokeColor=\"#FFFFFFFF\" android:strokeWidth=\"3.2\" android:strokeLineCap=\"round\" android:strokeLineJoin=\"round\" android:fillColor=\"#00000000\" android:pathData=\"M21,10h6M24,25l4,-4M24,13a12,12 0 1,0 0.01,0z\" />\n</vector>\n",
"res/drawable/pf_sc_train.xml": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<vector xmlns:android=\"http://schemas.android.com/apk/res/android\" android:width=\"48dp\" android:height=\"48dp\" android:viewportWidth=\"48\" android:viewportHeight=\"48\">\n    <path android:fillColor=\"#FFFF7A1A\" android:pathData=\"M24,0a24,24 0 1,0 0.01,0z\" />\n    <path android:strokeColor=\"#FFFFFFFF\" android:strokeWidth=\"3.2\" android:strokeLineCap=\"round\" android:strokeLineJoin=\"round\" android:fillColor=\"#00000000\" android:pathData=\"M16,17v14M32,17v14M11,21v6M37,21v6M16,24h16\" />\n</vector>\n",
